-- Applied transactionally by the embedded, versioned migration runner.
CREATE TABLE profiles (id uuid PRIMARY KEY, name text NOT NULL, years_experience integer NOT NULL DEFAULT 0 CHECK(years_experience>=0), location text NOT NULL DEFAULT '', skills jsonb NOT NULL DEFAULT '[]', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE profile_skills (id uuid PRIMARY KEY, profile_id uuid NOT NULL REFERENCES profiles(id) ON DELETE CASCADE, name text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(profile_id,name));
CREATE TABLE job_search_preferences (id uuid PRIMARY KEY REFERENCES profiles(id), roles jsonb NOT NULL DEFAULT '[]', required_skills jsonb NOT NULL DEFAULT '[]', seniorities jsonb NOT NULL DEFAULT '[]', countries jsonb NOT NULL DEFAULT '[]', remote jsonb NOT NULL DEFAULT '[]', employment_types jsonb NOT NULL DEFAULT '[]', excluded_companies jsonb NOT NULL DEFAULT '[]', excluded_keywords jsonb NOT NULL DEFAULT '[]', salary_min double precision NOT NULL DEFAULT 0, salary_max double precision NOT NULL DEFAULT 0, currency text NOT NULL DEFAULT 'IDR', salary_period text NOT NULL DEFAULT 'monthly', max_age_days integer NOT NULL DEFAULT 0, hard_remote boolean NOT NULL DEFAULT false, weights jsonb NOT NULL, discovery_minutes integer NOT NULL DEFAULT 360, auto_analyse boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE companies (id uuid PRIMARY KEY, name text NOT NULL UNIQUE, website text NOT NULL DEFAULT '', research_urls jsonb NOT NULL DEFAULT '[]', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE company_sources (id uuid PRIMARY KEY, company_id uuid NOT NULL REFERENCES companies(id) ON DELETE CASCADE, provider text NOT NULL CHECK(provider IN ('greenhouse','lever','lever-eu')), board text NOT NULL, enabled boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(provider,board));
CREATE TABLE jobs (id uuid PRIMARY KEY, company_id uuid NOT NULL REFERENCES companies(id), company_name text NOT NULL, title text NOT NULL, description text NOT NULL DEFAULT '', location text NOT NULL DEFAULT '', country text NOT NULL DEFAULT '', remote text NOT NULL DEFAULT 'unknown', seniority text NOT NULL DEFAULT '', min_experience integer, employment_type text NOT NULL DEFAULT '', salary_min double precision, salary_max double precision, currency text NOT NULL DEFAULT '', salary_period text NOT NULL DEFAULT '', canonical_url text NOT NULL UNIQUE, dedupe_key text NOT NULL, fingerprint text NOT NULL, source_payload jsonb NOT NULL, posted_at timestamptz, first_seen timestamptz NOT NULL, last_seen timestamptz NOT NULL, available boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX jobs_company_idx ON jobs(company_id); CREATE INDEX jobs_freshness_idx ON jobs(first_seen DESC); CREATE INDEX jobs_filter_idx ON jobs(available,remote); CREATE INDEX jobs_dedupe_idx ON jobs(company_id,dedupe_key);
CREATE TABLE job_observations (id uuid PRIMARY KEY, job_id uuid NOT NULL REFERENCES jobs(id) ON DELETE CASCADE, source_id uuid NOT NULL REFERENCES company_sources(id), external_id text NOT NULL, url text NOT NULL, payload jsonb NOT NULL, last_seen timestamptz NOT NULL, missing_runs integer NOT NULL DEFAULT 0, available boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(source_id,external_id));
CREATE INDEX observations_job_idx ON job_observations(job_id);
CREATE TABLE job_analyses (id uuid PRIMARY KEY, job_id uuid NOT NULL REFERENCES jobs(id) ON DELETE CASCADE, model text NOT NULL, prompt_version text NOT NULL, input_fingerprint text NOT NULL, result jsonb NOT NULL, input_tokens integer NOT NULL DEFAULT 0, output_tokens integer NOT NULL DEFAULT 0, estimated_cost double precision, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(job_id,input_fingerprint));
CREATE TABLE ai_usage (id uuid PRIMARY KEY, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE company_evidence (id uuid PRIMARY KEY, company_id uuid NOT NULL REFERENCES companies(id), source_url text NOT NULL, source_name text NOT NULL, published_at timestamptz, retrieved_at timestamptz NOT NULL, summary text NOT NULL, category text NOT NULL, confidence text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(company_id,source_url));
CREATE TABLE company_research (id uuid PRIMARY KEY, company_id uuid NOT NULL UNIQUE REFERENCES companies(id), status text NOT NULL, summary text NOT NULL, errors jsonb NOT NULL DEFAULT '[]', expires_at timestamptz NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE applications (id uuid PRIMARY KEY, job_id uuid NOT NULL UNIQUE REFERENCES jobs(id), stage text NOT NULL CHECK(stage IN ('Saved','Applied','Screening','Interview','Offer','Rejected','Withdrawn')), notes text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX applications_stage_idx ON applications(stage);
CREATE TABLE discovery_runs (id uuid PRIMARY KEY, status text NOT NULL, jobs_seen integer NOT NULL DEFAULT 0, errors jsonb NOT NULL DEFAULT '[]', finished_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
